type Inline =
  | string
  | { tag: 'strong' | 'em' | 'code'; text: string }
  | { tag: 'a'; text: string; href: string }
export type Block =
  | { tag: 'h1' | 'h2' | 'p'; inline: Inline[] }
  | { tag: 'img'; alt: string; src: string }
  | { tag: 'ul'; items: Inline[][] }

